// Температура жидкостей GregTech — для проверки жаростойкости труб (труба мода горит, если жидкость горячее её
// mHeatResistance: MTEFluidPipe). Из кода мода (gregtech-*.jar, разбор байткода через javap):
//  — жидкости и газы с явной температурой: LoaderGTBlockFluid, withStateAndTemperature (пар — 375 K);
//  — расплавы «Molten X»: температура плавления материала X (MaterialsInit, setMeltingPoint), не задана — 1000 K
//    (GTProxy.addAutogeneratedMoltenFluid);
//  — плазма — 10 000 K (GTProxy.addAutogeneratedPlasmaFluid) — правилом в коде сайта, не здесь.
// Остальные жидкости — комнатные 295 K (Materials.getLiquidTemperature без точки плавления).
// Пишет lib/calc/fluid-temps.ts: английское имя жидкости → кельвины.
// Запуск: node scripts/fluid-temps.mjs "<папка игры>"
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { unzipSync } from "fflate";

const game = process.argv[2];
if (!game || !existsSync(path.join(game, "mods"))) throw new Error("Укажите папку игры (в ней должна быть папка mods)");
const mods = path.join(game, "mods");
const jar = readdirSync(mods).find((name) => /^gregtech-[\d.]+\.jar$/i.test(name));
if (!jar) throw new Error("Нет gregtech-*.jar в папке mods");

const FLUIDS = "gregtech/loaders/preload/LoaderGTBlockFluid.class";
const MATERIALS = "gregtech/loaders/materials/MaterialsInit.class";
const files = unzipSync(readFileSync(path.join(mods, jar)), { filter: (file) => [FLUIDS, MATERIALS].includes(file.name) });
const temp = mkdtempSync(path.join(os.tmpdir(), "fluid-temps-"));
const javap = (name) => {
  const file = path.join(temp, path.basename(name));
  writeFileSync(file, files[name]);
  return execFileSync("javap", ["-c", "-p", file], { encoding: "utf8", maxBuffer: 1 << 28 }).split(/\r?\n/);
};
const intOf = (line) => /(?:bipush|sipush)\s+(-?\d+)/.exec(line)?.[1] ?? /\/\/ int (-?\d+)/.exec(line)?.[1] ?? /iconst_(\d)/.exec(line)?.[1];
const stringOf = (line) => /\/\/ String (.+)$/.exec(line)?.[1];

const temps = new Map();

// Расплавы: материал строится построителем — имя для людей и точка плавления; запись — на constructMaterial.
let localName;
let melting;
let lastInt;
for (const line of javap(MATERIALS)) {
  const int = intOf(line);
  if (int !== undefined) lastInt = Number(int);
  if (/MaterialBuilder\."<init>"/.test(line)) {
    localName = undefined;
    melting = undefined;
  }
  const text = stringOf(line);
  if (text !== undefined) lastInt = undefined;
  if (/setDefaultLocalName/.test(line)) localName = lastString;
  if (/setMeltingPoint/.test(line)) melting = lastInt;
  if (/constructMaterial/.test(line) && localName) temps.set(`Molten ${localName}`, melting !== undefined && melting >= 0 ? melting : 1000);
  if (text !== undefined) var lastString = text;
}

// Жидкости с явной температурой: builder(имя) … withDefaultLocalName(название) … withStateAndTemperature(состояние, K).
let display;
for (const line of javap(FLUIDS)) {
  const int = intOf(line);
  if (int !== undefined) lastInt = Number(int);
  const text = stringOf(line);
  if (/GTFluidFactory\.builder/.test(line)) display = undefined;
  if (text !== undefined) display = text;
  if (/withStateAndTemperature/.test(line) && display && lastInt !== undefined) temps.set(display, lastInt);
}

const entries = [...temps].filter(([, kelvin]) => kelvin !== 295).sort(([a], [b]) => a.localeCompare(b));
const out = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "lib", "calc", "fluid-temps.ts");
writeFileSync(
  out,
  `/**
 * Температура жидкостей GregTech в кельвинах (${jar}): расплавы — точка плавления материала (MaterialsInit), жидкости и
 * газы с явной температурой — LoaderGTBlockFluid. Не в списке — 295 K; плазма — 10 000 K (правилом в conduits.ts).
 * Создано скриптом scripts/fluid-temps.mjs — не править руками.
 */
export const FLUID_TEMPS: Readonly<Record<string, number>> = {
${entries.map(([name, kelvin]) => `  ${JSON.stringify(name)}: ${kelvin},`).join("\n")}
};
`,
);
console.log(`жидкостей: ${entries.length}; пар: ${temps.get("Steam")}; расплав стали: ${temps.get("Molten Steel")}; олова: ${temps.get("Molten Tin")}`);
